use std::{error::Error, fmt::Write, path::Path};
pub fn write(path: &Path) -> Result<(), Box<dyn Error>> {
    let mut output = String::from(
        "# Strata command reference\n\nGenerated by `strata-devtool docs`; edit the Rust registry and parameter types, then regenerate. Examples use host fixture aliases, never arbitrary model-supplied paths.\n\n",
    );
    for spec in strata_core::commands::catalog() {
        writeln!(
            output,
            "## `{}` — {}\n\n{}\n\nKind: `{:?}` · Undoable: `{}` · Batchable: `{}`\n\nEffects: `{}`\n\nPermissions: `{}`\n",
            spec.id,
            spec.title_zh,
            spec.description,
            spec.kind,
            spec.undoable,
            spec.batchable,
            spec.effects.join(", "),
            spec.permissions.join(", ")
        )?;
        for condition in &spec.preconditions {
            writeln!(output, "- {condition}")?;
        }
        writeln!(
            output,
            "\n### Parameters\n\n```json\n{}\n```\n\n### Result\n\n```json\n{}\n```\n\n### Examples\n",
            serde_json::to_string_pretty(&spec.params)?,
            serde_json::to_string_pretty(&spec.returns)?
        )?;
        for example in &spec.examples {
            writeln!(
                output,
                "```json\n{}\n```\n",
                serde_json::to_string_pretty(example)?
            )?;
        }
    }
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, output)?;
    Ok(())
}
